package ticketing

import (
	"context"
	capabilities "github.com/domainry-evals/s1-ticketing/generated/capabilities"
)

// Assign implements the project-owned ticket.assign Handler.
func Assign(ctx context.Context, caps capabilities.AssignCapabilities, input capabilities.AssignInput) (capabilities.AssignOutput, error) {
	_ = ctx
	_ = caps
	_ = input
	return capabilities.AssignOutput{}, capabilities.NewAssignNotImplementedError()
}

