package ticketing

import (
	"errors"
	capabilities "github.com/domainry-evals/s1-ticketing/generated/capabilities"
	"testing"
)

func TestAssignSeedFailsClosed(t *testing.T) {
	_, err := Assign(t.Context(), capabilities.AssignCapabilities{}, capabilities.AssignInput{})
	var businessError *capabilities.BusinessError
	if !errors.As(err, &businessError) || businessError.Code != "ticket.assign.not_implemented" {
		t.Fatalf("unexpected seed error: %T %v", err, err)
	}
}

