package ticketing

import (
	"context"
	"time"

	capabilities "github.com/domainry-evals/s1-ticketing/generated/capabilities"
	"github.com/domainry-evals/s1-ticketing/generated/data"
	"github.com/domainry-evals/s1-ticketing/generated/schema"
)

const (
	assignInputInvalidCode       = "ticket.assign.input_invalid"
	assignExecutionRequiredCode  = "ticket.assign.execution_required"
	assignCapabilityRequiredCode = "ticket.assign.capability_required"
	assignClosedCode             = "ticket.assign.closed"
	assignConflictCode           = "ticket.assign.conflict"
)

// Assign implements the project-owned ticket.assign Handler.
func Assign(ctx context.Context, caps capabilities.AssignCapabilities, input capabilities.AssignInput) (capabilities.AssignOutput, error) {
	var output capabilities.AssignOutput
	if caps.Execution == nil {
		return output, assignError(assignExecutionRequiredCode, "Action execution is required")
	}
	if caps.Ticket == nil || caps.Notifications == nil {
		return output, assignError(assignCapabilityRequiredCode, "Ticket and notification capabilities are required")
	}
	if input.AssigneeID == "" || input.RequestID == "" {
		return output, assignError(assignInputInvalidCode, "Assignee and request identities are required")
	}

	ticketID := caps.Execution.TargetID()
	if ticketID == "" {
		return output, assignError(assignInputInvalidCode, "Target ticket identity is required")
	}
	principal := caps.Execution.Principal()

	locked, err := caps.Ticket.GetForUpdate(ctx, ticketID)
	if err != nil {
		return output, err
	}
	if locked.Status == schema.TicketStatusClosed {
		return output, assignError(assignClosedCode, "Closed tickets cannot be assigned")
	}

	mutation := data.NewTicketUpdate(ticketID).
		SetAssigneeID(input.AssigneeID).
		WithExpectedUpdatedAt(locked.UpdatedAt)
	if locked.AssigneeID == nil {
		mutation = mutation.RequireAssigneeIDNull(assignConflictCode)
	} else {
		mutation = mutation.RequireAssigneeIDEqual(*locked.AssigneeID, assignConflictCode)
	}

	updated, err := caps.Ticket.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return output, err
	}
	if updated.ID == "" || updated.UpdatedAt == "" || updated.AssigneeID == nil || *updated.AssigneeID != input.AssigneeID {
		return output, assignError(assignConflictCode, "Ticket assignment result does not match the requested assignee")
	}

	assigneeID := input.AssigneeID
	actorUserID := principal.UserID
	_, err = caps.Notifications.Dispatch(ctx, capabilities.AssignNotificationIntent{
		EventType:        "ticket.assigned",
		SourceEventID:    input.RequestID,
		RecipientUserIDs: []string{input.AssigneeID},
		Surface:          principal.SurfaceKey,
		SubjectObjectKey: "ticket",
		SubjectRecordID:  string(updated.ID),
		SubjectVersion:   updated.UpdatedAt,
		DedupeKey:        input.RequestID,
		GroupKey:         "ticket:" + string(updated.ID),
		Alert:            true,
		OccurredAt:       time.Now().UTC(),
		Variables: []capabilities.AssignNotificationVariable{
			{Key: "assignee_id", StringValue: &assigneeID},
			{Key: "assigned_by_user_id", StringValue: &actorUserID},
		},
	})
	if err != nil {
		return output, err
	}

	return capabilities.AssignOutput{
		AssigneeID: input.AssigneeID,
		TicketID:   updated.ID,
	}, nil
}

func assignError(code, message string) error {
	return &capabilities.BusinessError{Code: code, Message: message}
}
