func TestAssignUpdatesTicketAndDispatchesInboxIntent(t *testing.T) {
	assigneeID := "user-support-2"
	ticketCapability := &assignTicketStub{
		locked: schema.Ticket{
			ID:        "ticket-1",
			UpdatedAt: "revision-1",
			Status:    schema.TicketStatusNew,
			Title:     "Printer unavailable",
		},
		updated: schema.Ticket{
			ID:         "ticket-1",
			UpdatedAt:  "revision-2",
			AssigneeID: &assigneeID,
			Status:     schema.TicketStatusNew,
			Title:      "Printer unavailable",
		},
	}
	notifications := &assignNotificationStub{}
	input := capabilities.AssignInput{AssigneeID: assigneeID, RequestID: "request-assign-1"}

	output, err := Assign(t.Context(), capabilities.AssignCapabilities{
		Execution: assignExecutionStub{
			principal: capabilities.Principal{UserID: "user-manager-1", RoleKey: "manager", SurfaceKey: "business_workspace", Known: true},
			targetID:  "ticket-1",
		},
		Ticket:        ticketCapability,
		Notifications: notifications,
	}, input)
	if err != nil {
		t.Fatalf("Assign returned error: %v", err)
	}
	if output.TicketID != "ticket-1" || output.AssigneeID != assigneeID {
		t.Fatalf("unexpected output: %#v", output)
	}
	if ticketCapability.getCalls != 1 || ticketCapability.conditionalCalls != 1 || ticketCapability.conditionalCheckErr != nil {
		t.Fatalf("unexpected ticket capability calls: get=%d conditional=%d validation=%v", ticketCapability.getCalls, ticketCapability.conditionalCalls, ticketCapability.conditionalCheckErr)
	}
	if len(notifications.intents) != 1 {
		t.Fatalf("expected one notification intent, got %d", len(notifications.intents))
	}
	intent := notifications.intents[0]
	if intent.EventType != "ticket.assigned" || intent.SourceEventID != input.RequestID || intent.DedupeKey != input.RequestID {
		t.Fatalf("unexpected notification identity: %#v", intent)
	}
	if len(intent.RecipientUserIDs) != 1 || intent.RecipientUserIDs[0] != assigneeID {
		t.Fatalf("unexpected notification recipients: %#v", intent.RecipientUserIDs)
	}
	if intent.Surface != "business_workspace" || intent.SubjectObjectKey != "ticket" || intent.SubjectRecordID != "ticket-1" || intent.SubjectVersion != "revision-2" {
		t.Fatalf("unexpected notification subject: %#v", intent)
	}
	if intent.OccurredAt.IsZero() {
		t.Fatal("notification occurrence time is required")
	}
}

