def command_cwd(project: Path, value: str) -> tuple[Path, str]:
    candidate = Path(value).expanduser()
    path = (candidate if candidate.is_absolute() else project / candidate).resolve(strict=True)
    if project != path and project not in path.parents:
        raise GateError("command cwd must remain inside the project")
    if path.is_symlink() or not path.is_dir():
        raise GateError("command cwd must be a real project directory")
    return path, path.relative_to(project).as_posix() if path != project else "."


def parse_expected_json(stdout: bytes) -> dict:
    if len(stdout) > MAX_EXPECTED_JSON_BYTES:
        raise GateError("expected JSON stdout exceeds the bounded validation limit")
    try:
        document = json.loads(stdout.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise GateError("command stdout is not one valid JSON document") from error
    if not isinstance(document, dict):
        raise GateError("command stdout JSON must be an object")
    return document


def project_check_proof(stdout: bytes, args) -> dict:
    document = parse_expected_json(stdout)
    if document.get("contract_version") != args.expect_json_contract:
        raise GateError("command JSON contract did not match expectation")
    if document.get("state") != args.expect_json_state:
        raise GateError("command JSON state did not match expectation")
    if document.get("scope") != "actions":
        raise GateError("project check JSON scope is not actions")
    issue_count = document.get("issue_count", 0)
    diagnostics = document.get("diagnostics")
    if diagnostics is None and document.get("state") == "valid" and issue_count == 0:
        diagnostics = []
    if not isinstance(diagnostics, list) or len(diagnostics) > MAX_DIAGNOSTICS or issue_count != len(diagnostics):
        raise GateError("project check diagnostic inventory is inconsistent or exceeds its bound")
    if any(not isinstance(value, dict) or not isinstance(value.get("code"), str) for value in diagnostics):
        raise GateError("project check diagnostic inventory has an invalid row")
    expected_codes = sorted(set(args.expect_json_diagnostic_code))
    actual_codes = sorted({value["code"] for value in diagnostics})
    if args.expect_json_state == "valid":
        if issue_count != 0 or expected_codes:
            raise GateError("valid project check must have an empty diagnostic inventory")
    elif not diagnostics or not expected_codes or actual_codes != expected_codes:
        raise GateError("invalid project check diagnostic codes did not match expectation")
    bounded = []
    allowed_fields = ("code", "path", "line", "column", "symbol", "owner", "category")
    for value in diagnostics:
        bounded.append({key: value[key] for key in allowed_fields if key in value})
    return {
        "contract_version": document["contract_version"],
        "state": document["state"],
        "scope": document["scope"],
        "issue_count": issue_count,
        "diagnostics": bounded,
        "diagnostics_sha256": sha256_bytes(json.dumps(diagnostics, sort_keys=True, separators=(",", ":")).encode("utf-8")),
    }


def source_finalization_proof(project: Path) -> dict:
    item = evidence_item(project, FINALIZATION_RECEIPT)
    validate_source_finalization(
        project,
        {"label": "Current local composition is finalized"},
        [item],
        ["source"],
    )
    return {"source_finalization_receipt": item}


def require_gate(state: dict, gate_id: str) -> dict:
    gate = state["gates"].get(gate_id)
    if not gate or not gate.get("active", True):
        raise GateError(f"unknown active gate ID: {gate_id}")
    return gate


def bind_gate(gate: dict, status: str, evidence_type: str, evidence: list[dict],
              bindings: list[str], identity: dict, note: str) -> None:
    if status not in STATUSES:
        raise GateError("unsupported gate status")

def command_run(args, project: Path, session: str) -> int:
    if not args.command:
        raise GateError("run requires a command after --")
    bindings = sorted(set(args.bind))
    if not bindings or any(value not in BINDINGS for value in bindings):
        raise GateError("run requires valid identity bindings")
    state = sync_gates(project, session, load_state(project, session))
    gate = require_gate(state, args.gate_id)
    validate_gate_dependencies(project, state, gate)
    validate_safe_argv(args.command)
    kind = validate_command_for_gate(gate["label"], args.command, project)
    execution_cwd, receipt_cwd = command_cwd(project, args.cwd)
    if args.expect_exit != 0 and (
        kind != "project_check"
        or "diagnostic inventory" not in gate["label"].lower()
    ):
        raise GateError("nonzero expectation is limited to an explicit project-check diagnostic inventory Gate")
    if kind == "project_check":
        if (
            args.expect_exit == 0
            and not args.expect_json_contract
            and not args.expect_json_state
            and not args.expect_json_diagnostic_code
        ):
            # Compatibility for the original successful `run -- <project check>`
            # call: its only valid meaning is the strict exit-0/valid contract.
            args.expect_json_contract = PROJECT_CHECK_CONTRACT
            args.expect_json_state = "valid"
        if args.expect_json_contract != PROJECT_CHECK_CONTRACT:
            raise GateError(f"project check requires --expect-json-contract {PROJECT_CHECK_CONTRACT}")
        if args.expect_json_state not in {"valid", "invalid"}:
            raise GateError("project check requires --expect-json-state valid or invalid")
        if args.expect_json_state == "valid" and args.expect_exit != 0:
            raise GateError("valid project check requires expected exit 0")
        if args.expect_json_state == "invalid" and args.expect_exit != 1:
            raise GateError("invalid project check requires expected exit 1")
    elif args.expect_json_contract or args.expect_json_state or args.expect_json_diagnostic_code:
        raise GateError("JSON expectations are supported only for project check")
    started_at = now()
    started_ns = time.monotonic_ns()
    completed = subprocess.run(args.command, cwd=execution_cwd, capture_output=True, text=False, check=False)
    duration_ms = (time.monotonic_ns() - started_ns) / 1_000_000
    root = evidence_root(project, session)
    root.mkdir(parents=True, exist_ok=True)
    receipt_path = root / f"{slug(args.gate_id)}-{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')}.json"
    expectation_error = ""
    proof = {}
    try:
        if completed.returncode != args.expect_exit:
            raise GateError(
                f"command exit {completed.returncode} did not match expected exit {args.expect_exit}"
            )
        if kind == "project_check":
            proof["project_check"] = project_check_proof(completed.stdout, args)
        elif kind == "source_finalize":
            proof.update(source_finalization_proof(project))
    except (GateError, OSError, json.JSONDecodeError) as error:
        expectation_error = str(error)
    expectation_met = not expectation_error
    identity = identities(project)
    receipt = {
        "contract_version": COMMAND_RECEIPT_VERSION,
        "gate_id": args.gate_id,
        "argv": args.command,
        # Retain the v1 field for readers created before argv was made explicit.
        "command": args.command,
        "cwd": receipt_cwd,
        "started_at": started_at,
        "completed_at": now(),
        "verified_at": now(),
        "duration_ms": round(duration_ms, 3),
        "exit_code": completed.returncode,
        "stdout_sha256": sha256_bytes(completed.stdout),
        "stderr_sha256": sha256_bytes(completed.stderr),
        "stdout_bytes": len(completed.stdout),
        "stderr_bytes": len(completed.stderr),
        "bindings": bindings,
        "identity": identity,
        "expectation": {
            "expected_exit": args.expect_exit,
            "json_contract": args.expect_json_contract,
            "json_state": args.expect_json_state,
            "json_diagnostic_codes": sorted(set(args.expect_json_diagnostic_code)),
            "met": expectation_met,
            "error": expectation_error,
        },
        "proof": proof,
    }
    atomic_json(receipt_path, receipt)
    evidence = [evidence_item(project, str(receipt_path))]
    status = "passed" if expectation_met else "failed"
    if status == "passed":
        validate_source_finalization(project, gate, evidence, bindings)
    bind_gate(gate, status, "command_receipt", evidence, bindings, identity, args.note)
    save(project, session, state)
    relative_receipt = receipt_path.relative_to(project).as_posix()
    output = dict(
        gate,
        run_contract_version=RUN_RESULT_VERSION,
        runner_state=status,
        expectation_met=expectation_met,
        expectation_error=expectation_error,
        command_exit_code=completed.returncode,
        evidence_path=relative_receipt,
        command_receipt={
